import time, random
from heapq import heappush, heappop
from collections import deque
random.seed(5)
N=4096; E=16384
edges=[]
for i in range(N-1): edges.append((i,i+1,1,'step%05d'%i,-1))
for i in range(E-(N-1)):
    edges.append((random.randrange(N),random.randrange(N),1+random.randrange(1000),'c%06d'%i,-1 if i%8 else i%1024))
out=[[] for _ in range(N)]; inn=[[] for _ in range(N)]
for (u,v,c,cmd,g) in edges:
    out[u].append((v,c,cmd,g)); inn[v].append((u,c,cmd,g))
masks=[bytes([1 if random.random()<0.5 else 0 for _ in range(1024)]) for _ in range(32)]
INF=float('inf')

def search_split(mask):
    dist=[INF]*N; dist[0]=0; heap=[(0,0)]; push=heappush; pop=heappop
    while heap:
        cost,state=pop(heap)
        if cost!=dist[state]: continue
        for (target,weight,_cmd,guard) in out[state]:
            if guard>=0 and not mask[guard]: continue
            f=cost+weight
            if f<dist[target]: dist[target]=f; push(heap,(f,target))
    steps=[-1]*N; steps[0]=0; q=deque([0])
    while q:
        u=q.popleft(); ns=steps[u]+1
        for (target,weight,_cmd,guard) in out[u]:
            if guard>=0 and not mask[guard]: continue
            if steps[target]<0 and dist[target]==dist[u]+weight:
                steps[target]=ns; q.append(target)
    return dist,steps

def search_tuple(mask):
    dist=[INF]*N; steps=[0]*N; dist[0]=0
    heap=[(0,0,0)]; push=heappush; pop=heappop
    while heap:
        cost,step,state=pop(heap)
        if cost!=dist[state] or step!=steps[state]: continue
        ns=step+1
        for (target,weight,_cmd,guard) in out[state]:
            if guard>=0 and not mask[guard]: continue
            f=cost+weight
            if f<dist[target] or (f==dist[target] and ns<steps[target]):
                dist[target]=f; steps[target]=ns; push(heap,(f,ns,target))
    return dist,steps

def reverse_bfs(mask,dist,steps,target):
    back=[-1]*N; back[target]=0; q=deque([target])
    while q:
        v=q.popleft(); nb=back[v]+1; dv=dist[v]
        for (u,c,_cmd,g) in inn[v]:
            if back[u]>=0: continue
            if g>=0 and not mask[g]: continue
            if dist[u]+c==dv:
                back[u]=nb; q.append(u)
    return back

for name,fn in [('split',search_split),('tuple',search_tuple)]:
    t=time.time()
    for m in masks: fn(m)
    print(name,'%.2f ms'%((time.time()-t)/len(masks)*1000))
d,s=search_tuple(masks[0])
d2,s2=search_split(masks[0])
print('agree:', d==d2, s==s2)
t=time.time()
for m in masks:
    dd,ss=search_tuple(m); reverse_bfs(m,dd,ss,random.randrange(N))
print('tuple+revbfs %.2f ms'%((time.time()-t)/len(masks)*1000))
